import { z } from "zod";

// Keys are stored in saved layouts; never rename one. Key order is the order offered in Settings.
export const BUILTIN_WIDGETS = { overview: "Overview", insights: "Weekly briefing", upcoming: "Coming up", spending: "Cash flow over six months, with where money came from and went",
  budgets: "Budgets", accounts: "Accounts", agents: "Agent team", history: "History of recent changes", recent: "Recent transactions", planning: "Available funds by account", goals: "Goals" };
// Home without a saved layout; the rest stay available in Settings.
const DEFAULT_WIDGETS = ["overview", "insights", "upcoming", "spending", "budgets", "accounts", "agents", "history"];
// Artifact cards on Home are stored as "card:<uuid>" next to the built-in keys.
const CARD_KEY = /^card:([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/;
const isWidgetKey = (key: string) => Object.hasOwn(BUILTIN_WIDGETS, key) || CARD_KEY.test(key);
// Retired page widgets may remain in saved layouts; discard them before validating current widgets.
export const dashboardLayoutSchema = z.array(z.string()).max(50)
  .transform(items => items.filter(key => !/^artifact:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(key)))
  .pipe(z.array(z.string().refine(isWidgetKey)).refine(items => new Set(items).size === items.length, "Widgets must be unique"));

export const cardWidgetKey = (id: string) => `card:${id.toLowerCase()}`;
export const cardIdFromKey = (key: string) => CARD_KEY.exec(key)?.[1] ?? null;

export function dashboardItems(saved: string[] | null) {
  return [...new Set(saved ?? DEFAULT_WIDGETS)].filter(isWidgetKey);
}

/** Adds a widget just below the overview (or first), so a newly added card is seen; or removes it. */
export function setWidget(items: string[], key: string, on: boolean) {
  if (!on) return items.filter(item => item !== key);
  if (items.includes(key)) return items;
  const at = items.indexOf("overview") + 1;
  return [...items.slice(0, at), key, ...items.slice(at)];
}
/** Home card sizes: grid columns of the six-column Home grid at desktop width, and the body area a card designs for. */
export const CARD_SIZES = {
  S: { label: "S", columns: 2, span: "lg:col-span-2", width: 340 },
  M: { label: "M", columns: 3, span: "lg:col-span-3", width: 520 },
  L: { label: "L", columns: 4, span: "lg:col-span-4", width: 700 },
  XL: { label: "XL", columns: 6, span: "lg:col-span-6", width: 1080 },
} as const;
export type CardSize = keyof typeof CARD_SIZES;
export const CARD_SIZE_KEYS = Object.keys(CARD_SIZES) as CardSize[];
/** Every card has the same fixed height, so Home rows line up and nothing scrolls. */
export const CARD_HEIGHT = 300;
/** Height left for the card's own content under the title row. */
export const CARD_BODY_HEIGHT = 236;
export const isCardSize = (value: unknown): value is CardSize => typeof value === "string" && Object.hasOwn(CARD_SIZES, value);
export const cardSize = (value: string): CardSize => isCardSize(value) ? value : "M";
import { NetWorthChart } from "./net-worth-chart";
import { shownBalance } from "./money/accounts/history";
import { LayoutGrid, Phone, Sparkle } from "lucide-react";

// Six columns: a wide card pairs with a narrow one and half cards pair up; dense flow fills the gaps whatever order the layout picks.
const FULL = new Set(["overview", "history"]);
const WIDE = new Set(["spending", "insights", "recent"]);
const HALF = new Set(["accounts", "agents"]);
const span = (key: string) => FULL.has(key) ? "lg:col-span-6" : WIDE.has(key) ? "lg:col-span-4" : HALF.has(key) ? "lg:col-span-3" : "lg:col-span-2";

export default async function Home({ searchParams }: { searchParams?: Promise<{ account?: string }> } = {}) {
  const params = await searchParams;
  const accountId = typeof params?.account === "string" ? params.account : undefined;
  const supabaseConfig = getSupabaseConfig();
  if (supabaseConfig.status !== "configured") return <main className="mx-auto max-w-3xl p-8">{supabaseConfig.detail}</main>;
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try {
    context = await requireWorkspace();
  } catch {
    redirect("/login");
  }
  const { supabase, workspace } = context;
  const displayCurrency: string = workspace.display_currency;
  const locale = workspace.locale;
  const money = (amount: bigint | string | number, currency: string) => formatMoney(amount, currency, locale);
  const today = calendarDate(new Date(), workspace.timezone);
  const balanceEvidencePromise = loadBalanceEvidence(supabase, workspace.id);
  const allWealthPromise = loadWealthItems(supabase, workspace.id, true);
  const wealthPromise = allWealthPromise.then(items => items.filter(item => !item.removed_at));
  const sourceMetadataPromise = loadSourceCoverageMetadata(supabase, workspace.id, true);
  // Start the streamed sections' reads now (memoized); their Suspense boundaries pick up the same promises. Recurring detection streams beside the page.
  loadInsightEvidence(supabase, workspace.id, displayCurrency, today).catch(() => undefined);
  loadHomeSpending(supabase, workspace.id, displayCurrency, today).catch(() => undefined);
  loadHomeHistory(supabase, workspace.id).catch(() => undefined);
  loadAgentBriefing(supabase, workspace.id).catch(() => undefined);
  const available = projection.available;
  const parsedLayout = layout.data ? dashboardLayoutSchema.safeParse(layout.data.items) : null;
  if (parsedLayout && !parsedLayout.success) throw new Error("Dashboard preferences are invalid; review them in Settings");
  const cards = new Map((pinned.data ?? []).map(row => [row.id as string, row as unknown as HomeCardRow & { artifact_id: string }]));
  // A deleted artifact simply drops off Home; its key is cleaned up the next time the layout is saved.
  const ordered = dashboardItems(parsedLayout?.success ? parsedLayout.data : null).filter(key => { const id = cardIdFromKey(key); return !id || cards.has(id); });
  // Cards on one Home share their reads: the same query runs once however many cards ask for it.
  const shared: QueryShared = {};
  const spanOf = (key: string) => { const id = cardIdFromKey(key); const size = id && cards.get(id)?.size; return isCardSize(size) ? CARD_SIZES[size].span : span(key); };
  const sectionProps = { db: supabase, workspaceId: workspace.id, currency: displayCurrency, today, locale };

  const widgets: Record<string, ReactNode> = {
    ...Object.fromEntries([...cards.values()].map(row => [`card:${row.id}`, <Suspense key={row.id} fallback={<CardSkeleton title={row.title} />}>
      <HomeCard card={row} context={context} shared={shared} open={`/ai/artifacts/${row.artifact_id}?tab=cards`} />
    </Suspense>])),
    overview: <section aria-label="Overview" className="grid gap-4 lg:grid-cols-3">
      <div className={`${card} flex flex-col gap-5 lg:col-span-2`}>
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex flex-wrap items-center gap-2.5"><h2 className="text-sm font-medium">Net worth</h2>
